 *
 * Tailwind CSS v4. Import after `@import "tailwindcss";`.
 */

@theme {
  /* surfaces, back to front */
  --color-page: var(--page);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-inset: var(--inset);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-field: var(--field);

  /* text, strongest to faintest */
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);

  /* hairlines */
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-line-soft: var(--line-soft);
  --color-grid-line: var(--grid-line);

  /* semantic */
  --color-bui-accent: var(--bui-accent);
  --color-bui-accent-ink: var(--bui-accent-ink);
  --color-bui-accent-tint: var(--bui-accent-tint);
  --color-green: var(--green);
  --color-green-tint: var(--green-tint);
  --color-orange: var(--orange);
  --color-orange-tint: var(--orange-tint);
  --color-red: var(--red);
  --color-red-tint: var(--red-tint);
  --color-tag-base: var(--tag-base);

  /* tooltip surface is self-contained so it can invert independently */
  --color-tooltip-bg: var(--tooltip-bg);
  --color-tooltip-fg: var(--tooltip-fg);
  --color-tooltip-muted: var(--tooltip-muted);
  --color-tooltip-border: var(--tooltip-border);

  /* zebra striping for data tables */
  --color-stripe: var(--stripe);
  --color-stripe-bg: var(--stripe-bg);

  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;

  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);

}

/*
 * `inline` substitutes the var() straight into the utility instead of adding
 * another indirection, so `shadow-card` resolves against whichever of
 * :root / .dark is in scope. Without it these would bake in the light values.
 */
@theme inline {
  --shadow-hairline: var(--shadow-hairline);
  --shadow-btn: var(--shadow-btn);
  --shadow-card: var(--shadow-card);
  --shadow-raised: var(--shadow-raised);
  --shadow-overlay: var(--shadow-overlay);
  --inset-shadow-field: var(--shadow-inset-field);
}

:root {

  --page: oklch(98.5% 0.001 286.376);
  --canvas: oklch(96.1% 0.002 247.84);
  --surface: oklch(100% 0 0);
  --inset: oklch(97.9% 0.002 247.839);
  --hover: oklch(97% 0.002 247.839);
  --hover-2: oklch(93.3% 0.003 247.86);
  --field: oklch(96.1% 0.001 286.375);

  --ink: oklch(24.7% 0.006 258.361);
  --ink-2: oklch(50.6% 0.01 264.477);
  --ink-3: oklch(69.5% 0.009 264.505);

  --line: oklch(94.6% 0.003 264.542);
  --line-strong: oklch(91.2% 0.005 258.326);
  --line-soft: oklch(96.6% 0.002 264.542);
  --grid-line: var(--line);

  --bui-accent: oklch(62.6% 0.205 254.947);
  --bui-accent-ink: oklch(55.6% 0.187 255.617);
  --bui-accent-tint: oklch(96% 0.019 252.878);
  --green: oklch(60.3% 0.155 150.883);
  --green-tint: oklch(95.8% 0.017 159.118);
  --orange: oklch(68.9% 0.179 49.902);
  --orange-tint: oklch(96.4% 0.021 67.581);
  --red: oklch(62.1% 0.192 23.042);
  --red-tint: oklch(95.6% 0.017 17.462);
  --tag-base: oklch(75.7% 0.153 66.401);

  --tooltip-bg: oklch(27.2% 0.008 264.435);
  --tooltip-fg: oklch(97.6% 0.002 247.839);
  --tooltip-muted: oklch(73.1% 0.008 260.731);
  --tooltip-border: oklch(35.6% 0.007 264.474);

  --stripe: oklch(40.5% 0 0 / 0.075);
  --stripe-bg: oklch(97% 0 0);

  /* base elevation scale — many small layers rather than one big blur */
  --shadow-xs: 0 0 4px 0 #0000000a;
  --shadow-sm: 0 18px 47px 0 #00000008, 0 7.5px 19px 0 #00000005,
    0 4px 10.5px 0 #00000005, 0 2.3px 5.8px 0 #00000003,
    0 1.2px 3.1px 0 #00000003, 0 0.5px 1.3px 0 #00000003;
  --shadow-md: 0 17.54px 23.39px 0 #0000000a, 0 9.4px 12.5px 0 #00000008,
    0 5.25px 7px 0 #00000005, 0 2.79px 3.72px -2px #00000003,
    0 1.16px 1.5px 0 #00000003;
  --shadow-lg: 0 25px 50px 0 #0000000d, 0 12px 24px 0 #0000000a,
    0 6px 12px 0 #00000008, 0 3px 6px 0 #00000005, 0 1.5px 3px 0 #00000005;

  /* every elevated surface carries its own 1px ring instead of a border */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0% 0 0 / 0.12);
}

.dark {
  --page: oklch(20.9% 0.004 264.477);
  --canvas: oklch(23.1% 0.004 264.487);
  --surface: oklch(26% 0.006 271.191);
  --inset: oklch(24.3% 0.004 264.492);
  --hover: oklch(28.9% 0.006 271.22);
  --hover-2: oklch(31.8% 0.007 274.747);
  --field: oklch(29.3% 0.006 271.223);

  --ink: oklch(96.4% 0.002 247.839);
  --ink-2: oklch(73.1% 0.008 260.731);
  --ink-3: oklch(54.1% 0.01 264.484);

  --line: oklch(30.8% 0.006 258.354);
  --line-strong: oklch(35.6% 0.007 264.474);
  --line-soft: oklch(27.8% 0.006 258.354);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);

  --bui-accent: oklch(68% 0.173 253.301);
  --bui-accent-ink: oklch(78.8% 0.113 248.33);
  --bui-accent-tint: oklch(68% 0.173 253.301 / 0.16);
  --green: oklch(70.5% 0.154 153.814);
  --green-tint: oklch(70.5% 0.154 153.814 / 0.14);
  --orange: oklch(74.6% 0.156 55.642);
  --orange-tint: oklch(74.6% 0.156 55.642 / 0.14);
  --red: oklch(66.6% 0.18 21.433);
  --red-tint: oklch(66.6% 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(18.2% 0.004 264.459);
  --tooltip-fg: oklch(96.4% 0.002 247.839);
  --tooltip-muted: oklch(73.1% 0.008 260.731);
  --tooltip-border: oklch(30.8% 0.006 258.354);

  --stripe: oklch(100% 0 0 / 0.055);
  --stripe-bg: oklch(22.6% 0.004 264.485);

  /* rings flip to white-on-dark; drop shadows get heavier to stay readable */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-btn: 0 0 0 1px oklch(100% 0 0 / 0.1), 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-card: 0 0 0 1px oklch(100% 0 0 / 0.11), 0 1px 2px oklch(0% 0 0 / 0.2),
    0 2px 6px oklch(0% 0 0 / 0.2);
  --shadow-raised: 0 0 0 1px oklch(100% 0 0 / 0.13), 0 2px 10px oklch(0% 0 0 / 0.22);
  --shadow-overlay: 0 0 0 1px oklch(100% 0 0 / 0.15), 0 8px 28px oklch(0% 0 0 / 0.34);
  --shadow-inset-field: inset 0 1px 2px oklch(0% 0 0 / 0.4);
}

@utility rounded-window {
  border-radius: var(--radius-window);
}

@keyframes bui-shimmer-text {
  to {
    background-position: -200% center;
  }
}

@keyframes bui-fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes bui-caret {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@keyframes bui-pixel-on {
  0%,
  100% {
    opacity: 0.15;
  }
  50% {
    opacity: 1;
  }
}

@keyframes bui-pop-in {
  from {
    transform: scale(0.6);
    opacity: 0;
  }
  60% {
    transform: scale(1.08);
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  /* Scoped to this library's own keyframes — a component set shouldn't decide
     the host app's motion policy. The shimmer and pixel loops are decorative;
     the state they signal is always carried by text or an aria-live region too. */
  [style*="bui-shimmer-text"],
  [style*="bui-fade-up"],
  [style*="bui-pixel-on"],
  [style*="bui-pop-in"],
  [style*="bui-caret"] {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
